export interface Banner {
  id: string;
  /** Base path without size suffix or extension. */
  base: string;
  /** Intrinsic size of the original artwork. */
  width: number;
  height: number;
  /** Product title shown as HTML beneath the banner. */
  title: string;
  productSlug: string;
  /** Describes the artwork, including its baked-in headline. */
  alt: string;
}

